use smaul_native::rl::SmaulRl;
use std::env;
fn val(name:&str,default:&str)->String{let a:Vec<String>=env::args().collect();a.windows(2).find(|x|x[0]==name).map(|x|x[1].clone()).unwrap_or_else(||default.into())}
fn main(){let model=val("--model","./SmaulNative");let work=val("--work-dir","./rl");let prompts:Vec<String>=env::args().skip_while(|x|x!="--prompt").skip(1).filter(|x|!x.starts_with("--")).collect();if prompts.is_empty(){eprintln!("use --prompt <text> [--prompt <text> ...]");std::process::exit(2)}let responses:usize=val("--responses","8").parse().unwrap();let max_new:usize=val("--max-new-tokens","256").parse().unwrap();let temp:f32=val("--temperature","0.8").parse().unwrap();let top_k:usize=val("--top-k","50").parse().unwrap();let top_p:f32=val("--top-p","0.95").parse().unwrap();let lr:f32=val("--rl-lr","1e-6").parse().unwrap();let mut rl=SmaulRl::load(model,work).unwrap_or_else(|e|{eprintln!("{e}");std::process::exit(1)});rl.run_human(&prompts,responses,max_new,temp,top_k,top_p,lr).unwrap_or_else(|e|{eprintln!("{e}");std::process::exit(1)})}
